const reports = $input.all();

if (reports.length === 0) {
  return {
    json: {
      no_reports: true,
      message: 'No reports generated this week'
    }
  };
}

// Group by user email
const userReports = {};
reports.forEach(r => {
  const email = r.json.fields.user_email;
  if (!userReports[email]) {
    userReports[email] = [];
  }
  userReports[email].push(r.json.fields);
});

// Create digest for each user
const digests = [];
for (const [email, userReportList] of Object.entries(userReports)) {
  const avgConfidence = userReportList.reduce((sum, r) => sum + parseFloat(r.confidence_score || 0), 0) / userReportList.length;

  digests.push({
    user_email: email,
    report_count: userReportList.length,
    avg_confidence: avgConfidence.toFixed(2),
    reports: userReportList.map(r => ({
      report_id: r.report_id,
      company: r.company_name,
      confidence: r.confidence_score,
      question: r.strategic_question.substring(0, 100) + '...'
    })),
    week_start: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
    week_end: new Date().toISOString().split('T')[0]
  });
}

return digests.map(d => ({ json: d }));

